function findKthLargest(nums, k) {
  const heap = Heap.from(nums, (a, b) => b - a);   // a max-heap of all n values, in O(n)
  for (let i = 1; i < k; i++) heap.pop();          // remove the k - 1 largest
  return heap.peek();                              // the kth largest is on top
}

int findKthLargest(int[] nums, int k) {
    PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());   // max-heap
    for (int x : nums) heap.offer(x);
    for (int i = 1; i < k; i++) heap.poll();     // remove the k - 1 largest
    return heap.peek();                          // the kth largest is on top
}

