function findKthLargest(nums, k) {
  const heap = new Heap();                   // a min-heap of the k largest seen so far
  for (const x of nums) {
    heap.push(x);
    if (heap.size() > k) heap.pop();         // drop the smallest: it can't be in the top k
  }
  return heap.peek();                        // the smallest of the k largest
}

import heapq

def find_kth_largest(nums, k):
    heap = []                                # a min-heap of the k largest seen so far
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)              # drop the smallest: it can't be in the top k
    return heap[0]                           # the smallest of the k largest

int findKthLargest(int[] nums, int k) {
    PriorityQueue<Integer> heap = new PriorityQueue<>();   // a min-heap of the k largest so far
    for (int x : nums) {
        heap.offer(x);
        if (heap.size() > k) heap.poll();    // drop the smallest: it can't be in the top k
    }
    return heap.peek();                      // the smallest of the k largest
}

int findKthLargest(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;   // a min-heap of the k largest so far
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();   // drop the smallest: it can't be in the top k
    }
    return heap.top();                          // the smallest of the k largest
}
